<div class="card"><h1>User Reports</h1><table><tr><th>Reported</th><th>Reporter</th><th>Reason</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['reported_name']) ?></td><td><?= e($r['reporter_name']) ?></td><td><?= e($r['reason']) ?><br><?= e($r['description']) ?></td><td><?= e($r['status']) ?></td><td><form method="post"><input type="hidden" name="report_id" value="<?= $r['id'] ?>"><input type="hidden" name="warn_user_id" value="<?= $r['reported_user_id'] ?>"><select name="status"><option value="resolved">Resolve + Warning</option><option value="escalated">Escalate to Admin</option><option value="dismissed">Dismiss</option></select><input name="moderator_note" placeholder="Note"><button>Save</button></form></td></tr><?php endforeach; ?></table></div>
